{"language": "css", "code": "/* Custom CSS for Adi's Portfolio */

/* CSS Reset & Variable Definitions */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

:root {
    /* Color Palette: Earthy, desaturated dark greens (subtle transition) */
    --bg-left: #101714;
    /* Deepest dark organic pine green */
    --bg-right: #15221b;
    /* Slightly lighter desaturated warm forest green */
    --divider-color: #21332a;
    /* Subtle divider border */

    --text-primary: #d5ded7;
    /* Soft sage-tinted off-white */
    --text-muted: #829488;
    /* Muted earthy sage green */

    /* Header & Nav */
    --header-bg: rgba(16, 23, 20, 0.65);
    --header-border: rgba(33, 51, 42, 0.45);

    /* Typography */
    --font-heading: "Bungee", sans-serif;
    --font-body: "Inter", system-ui, -apple-system, sans-serif;
}

html {
    width: 100%;
    min-height: 100%;
    scroll-behavior: smooth;
    /* Smooth scrolling for nav anchor links */
    overflow-x: hidden;
}

body {
    width: 100%;
    min-height: 100vh;
    position: relative;
    /* Visual overlays bind relative to full body document height */
    background-color: var(--bg-right);
    color: var(--text-primary);
    font-family: var(--font-body);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;

    /* Hide cursor on desktop only if JS loaded custom cursor */
    @media (pointer: fine) {

        body.has-custom-cursor,
        body.has-custom-cursor * {
            cursor: none !important;
        }
    }

    /* Interactive Canvas Overlay */
    #interaction-canvas {
        position: fixed;
        /* Fixed to viewport so it tracks mouse globally */
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: 15;
        /* Above text for trail visual, pointer-events none makes it hover-through */
        pointer-events: none;
    }

    /* ------------------------------------------------------------- */
    /* Site Header & Navigation (Glassmorphic)                       */
    /* ------------------------------------------------------------- */
    .site-header {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 80px;
        background-color: var(--header-bg);
        backdrop-filter: blur(12px) saturate(120%);
        -webkit-backdrop-filter: blur(12px) saturate(120%);
        border-bottom: 1px solid var(--header-border);
        z-index: 100;
        transition: background-color 0.3s ease, border-color 0.3s ease;
    }

    .header-container {
        display: flex;
        justify-content: space-between;
        align-items: center;
        width: 100%;
        height: 100%;
        max-width: 1440px;
        margin: 0 auto;
        padding: 0 4rem;
    }

    /* Brand Logo "A." */
    .site-logo {
        font-family: var(--font-heading);
        font-weight: 400;
        font-size: 1.6rem;
        color: var(--text-primary);
        text-decoration: none;
        transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        display: inline-block;
    }

    .site-logo:hover {
        transform: scale(1.15) rotate(-5deg);
    }

    /* Desktop Navigation Menu */
    .site-nav {
        display: flex;
        align-items: center;
    }

    .nav-list {
        display: flex;
        list-style: none;
        align-items: center;
        gap: 2.2rem;
    }

    .nav-link {
        font-family: var(--font-body);
        font-size: 0.75rem;
        font-weight: 500;
        letter-spacing: 0.15em;
        text-transform: uppercase;
        color: var(--text-muted);
        text-decoration: none;
        position: relative;
        padding: 0.5rem 0;
        transition: color 0.3s ease, transform 0.3s ease;
        display: inline-block;
    }

    .nav-link:hover {
        color: var(--text-primary);
        transform: translateY(-1px);
    }

    /* Custom underline reveal animation for nav links */
    .nav-link::after {
        content: "";
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        height: 1.5px;
        background-color: var(--text-primary);
        transform: scaleX(0);
        transform-origin: right center;
        transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    }

    .nav-link:hover::after {
        transform: scaleX(1);
        transform-origin: left center;
    }

    /* Active Nav State */
    .nav-link.active {
        color: var(--text-primary);
    }

    .nav-link.active::after {
        transform: scaleX(1);
    }

    /* Outline style for Resume button */
    .nav-link.resume-button {
        border: 1.2px solid rgba(130, 148, 136, 0.4);
        padding: 0.5rem 1.2rem;
        border-radius: 4px;
        transition: all 0.3s ease;
    }

    .nav-link.resume-button::after {
        display: none;
    }

    .nav-link.resume-button:hover {
        background-color: rgba(130, 148, 136, 0.1);
        border-color: var(--text-primary);
        transform: translateY(-1px);
    }

    /* Mobile Toggle Hamburger Button */
    .menu-toggle {
        display: none;
        background: none;
        border: none;
        flex-direction: column;
        justify-content: space-between;
        width: 24px;
        height: 18px;
        padding: 0;
        cursor: pointer;
        z-index: 110;
    }

    .hamburger-bar {
        width: 100%;
        height: 2px;
        background-color: var(--text-primary);
        transition: transform 0.3s ease, opacity 0.3s ease;
    }

    /* ------------------------------------------------------------- */
    /* Detailed SVG Neuron Background Layout                         */
    /* ------------------------------------------------------------- */
    /* 1. Neuron BG: Fixed to be behind content, auto-height to prevent bottom empty space */
    .neuron-bg-container {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: 1; /* Pushed to the back */
        pointer-events: none;
        overflow: hidden; /* Clips excess background */
    }

    #neuron-svg {
        position: absolute;
        top: -150px;
        right: 0;
        /* Hard-pins the Soma to the top right corner */
        width: 1440px !important;
        /* Locks dimensions to match SVG viewBox exactly */
        height: 4600px !important;
        max-width: none;
        /* Prevents browser from auto-shrinking the width */
        display: block;


    }

    /* Soma SVG illumination when hovered/active */
    #neuron-svg.soma-active #soma-body {
        stroke: rgba(220, 200, 255, 1);
        filter: drop-shadow(0 0 16px rgba(192, 132, 252, 0.9)) drop-shadow(0 0 4px rgba(255, 255, 255, 0.9));
    }

    #neuron-svg.soma-active #soma-logo {
        opacity: 1.0;
        filter: drop-shadow(0 0 12px rgba(192, 132, 252, 0.95)) drop-shadow(0 0 3px rgba(255, 255, 255, 0.9));
    }



    /* Text styles inside SVG Schematic */
    .notebook-label text {
        font-family: var(--font-body);
        font-size: 10px;
        font-weight: 500;
        letter-spacing: 0.15em;
        font-style: normal;
        text-shadow: 0 1px 2px rgba(16, 23, 20, 0.5);
    }

    /* ------------------------------------------------------------- */
    /* Hero Split Container & Taglines                              */
    /* ------------------------------------------------------------- */
    /* 2. Hero Container: Grid layout ensures content is on top */
    .hero-container {
        display: flex;
        flex-direction: row;
        width: 100%; /* Fixes horizontal scroll */
        height: 100vh;
        position: relative;
        z-index: 10; /* Ensures hero content is always above neuron */
        border-bottom: 2px solid var(--divider-color);
    }

    /* Subtle organic grain overlay texture */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.02;
        pointer-events: none;
< truncated lines 296-911 >
        line-height: 1.3;
        color: var(--text-muted);
        text-decoration: none;
        letter-spacing: 0.02em;
        transition: color 0.25s ease;
        pointer-events: auto;
        text-align: center;
    }

    .directory-item.active .directory-value {
        color: #00f0ff;
        text-shadow: 0 0 4px rgba(0, 240, 255, 0.35);
    }

    .directory-value:hover {
        text-decoration: underline;
    }

    /* SVG Keypad Button Interactive Styles */
    .key-button {
        pointer-events: bounding-box;
        pointer-events: all;


    }

    .key-button circle {
        fill: none;
        stroke: rgba(130, 148, 136, 0.35);
        transition: stroke 0.2s ease, fill 0.2s ease, filter 0.2s ease;
    }

    .key-button text {
        fill: rgba(130, 148, 136, 0.6);
        transition: fill 0.2s ease, font-weight 0.2s ease;
    }

    /* Keypad Hover State */
    .key-button:hover circle {
        stroke: rgba(213, 222, 215, 0.85);
        fill: rgba(130, 148, 136, 0.12);
    }

    .key-button:hover text {
        fill: rgba(213, 222, 215, 1);
    }

    /* Keypad Active/Selected State */
    .key-button:active circle,
    .key-button.key-active circle {
        stroke: #00f0ff;
        fill: rgba(0, 240, 255, 0.08);
        filter: drop-shadow(0 0 4px rgba(0, 240, 255, 0.35));
    }

    .key-button:active text,
    .key-button.key-active text {
        fill: #00f0ff;
        font-weight: 600;
    }

    /* ------------------------------------------------------------- */
    /* Keyframes & Media Queries                                     */
    /* ------------------------------------------------------------- */

    /* Organic Neuron Animations */
    #soma-group {
        transform-origin: 1118px 462px;
        animation: organicFloat 12s ease-in-out infinite;
    }

    .dendrite-bg {
        transform-origin: 1118px 462px;
        animation: parallaxSway 15s ease-in-out infinite alternate;
    }

    .dendrite-mid {
        animation: neuralPulse 4s ease-in-out infinite;
    }

    #soma-group circle {
        transform-origin: 1118px 462px;
        animation: coreBeat 3s ease-in-out infinite;
    }

    @keyframes organicFloat {

        0%,
        100% {
            transform: translate(0, 0) scale(1) rotate(0deg);
        }

        33% {
            transform: translate(4px, -6px) scale(1.02) rotate(1deg);
        }

        66% {
            transform: translate(-3px, 4px) scale(0.98) rotate(-0.5deg);
        }
    }

    @keyframes parallaxSway {
        0% {
            transform: rotate(0deg) scale(1);
        }

        100% {
            transform: rotate(-2deg) scale(1.03);
        }
    }

    @keyframes coreBeat {

        0%,
        100% {
            transform: scale(1);
            opacity: 0.7;
            filter: drop-shadow(0 0 10px rgba(192, 132, 252, 0.5));
        }

        50% {
            transform: scale(1.15);
            opacity: 1;
            filter: drop-shadow(0 0 25px rgba(216, 180, 254, 0.9));
        }
    }

    @keyframes neuralPulse {

        0%,
        100% {
            stroke: rgba(192, 132, 252, 0.55);
            filter: drop-shadow(0 0 4px rgba(192, 132, 252, 0.35));
        }

        50% {
            stroke: rgba(215, 185, 255, 0.85);
            filter: drop-shadow(0 0 12px rgba(192, 132, 252, 0.8));
        }
    }

    @keyframes revealRight {
        0% {
            opacity: 0;
            transform: translateX(-25px);
            filter: blur(4px);
        }

        100% {
            opacity: 1;
            transform: translateX(0);
            filter: blur(0);
        }
    }

    @media (max-width: 900px) {
        .header-container {
            padding: 0 2rem;
        }

        .hero-right {
            padding: 0 4vw;
        }
    }

    @media (max-width: 768px) {
        .menu-toggle {
            display: flex;
        }

        .site-nav {
